mapper.select:
SELECT * FROM ( SELECT T1.COMPLAIN_ID, COALESCE(T1.DELEGATE_ID, TP.DELEGATE_ID) AS DELEGATE_ID, T1.ACCOUNT_ID, T1.APPROVAL_STATUS_CD, T1.APPROVER_TYPE_CD, T1.APPROVAL_TYPE_CD, T1.PROCESS_DT, T1.APPROVAL_COMMENT, T1.SEQ_NO, T1.URL, T3.CATEGORY_CD, TC1.CODE_NAME AS CATEGORY_NAME, TC2.CODE_NAME AS APPROVAL_STATUS_NAME, TC3.CODE_NAME AS APPROVER_TYPE_NAME, TC4.CODE_NAME AS APPROVAL_TYPE_NAME, t1.create_dt, TU1.USER_NAME AS ACCOUNT_NAME,
COALESCE(TU2_HISTORY.USER_NAME, TU1.USER_NAME) AS PROCESSOR_NAME,
ROW_NUMBER() OVER ( ORDER BY CASE WHEN T1.PROCESS_DT IS NULL THEN 0 ELSE 1 END ASC, NVL(T1.PROCESS_DT, T1.CREATE_DT) DESC, T1.SEQ_NO DESC ) AS RNUM
FROM T2000_APPROVAL_HISTORY T1 INNER JOIN T2000_COMPLAIN T2 ON T1.COMPLAIN_ID = T2.COMPLAIN_ID LEFT JOIN T2000_COMPLAIN_CATEGORY T3 ON T2.COMPLAIN_CATEGORY_ID = T3.COMPLAIN_CATEGORY_ID LEFT JOIN TOTAL_CODE TC1 ON T3.CATEGORY_CD = TC1.CODE_ID AND TC1.GROUP_ID = 'G0' LEFT JOIN TOTAL_CODE TC2 ON T1.APPROVAL_STATUS_CD = TC2.CODE_ID AND TC2.GROUP_ID = 'E0' LEFT JOIN TOTAL_CODE TC3 ON T1.APPROVER_TYPE_CD = TC3.CODE_ID AND TC3.GROUP_ID = 'F0' LEFT JOIN TOTAL_CODE TC4 ON T1.APPROVAL_TYPE_CD = TC4.CODE_ID AND TC4.GROUP_ID = 'H0'
LEFT JOIN T1000_ACCOUNT TA1 ON T1.ACCOUNT_ID = TA1.ACCOUNT_ID LEFT JOIN T1000_USER TU1 ON TA1.USER_NO = TU1.USER_NO
LEFT JOIN T1000_ACCOUNT TA_HIS ON T1.DELEGATE_ID = TA_HIS.ACCOUNT_ID LEFT JOIN T1000_USER TU2_HISTORY ON TA_HIS.USER_NO = TU2_HISTORY.USER_NO
LEFT JOIN T2000_PROXY TP ON T1.ACCOUNT_ID = TP.ABS_ID AND SYSDATE BETWEEN TP.START_DT AND TP.END_DT AND TP.DEL_YN = 'N'
((T1.ACCOUNT_ID = #{accountId} OR T1.DELEGATE_ID = #{accountId}) OR (TP.DELEGATE_ID = #{accountId} AND T1.APPROVAL_TYPE_CD IS NULL))
AND T1.PROCESS_DT >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND T1.CREATE_DT < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND T1.APPROVAL_STATUS_CD = #{approvalStatusCd}
AND T3.CATEGORY_CD = #{categoryCd}
) WHERE RNUM BETWEEN #{startRow} AND #{endRow}

mapper.update:
UPDATE T2000_APPROVAL_HISTORY

    APPROVAL_STATUS_CD = #{approvalStatusCd},
    PROCESS_DT = SYSDATE,
    APPROVAL_COMMENT = #{approvalComment},


        DELEGATE_ID = #{delegateId},



        APPROVAL_TYPE_CD = #{approvalTypeCd}


WHERE COMPLAIN_ID = #{complainId}
  AND SEQ_NO = #{seqNo}
